sys_script.script:
(function executeRule(current, previous) {
    var SCORE_REASON_PAIRS = [
        { scoreField: 'quality_score', reasonField: 'quality_reason', label: 'Quality' },
        { scoreField: 'delivery_score', reasonField: 'delivery_reason', label: 'Delivery' },
        { scoreField: 'quantity_score', reasonField: 'quantity_reason', label: 'Quantity' },
        { scoreField: 'cost_score', reasonField: 'cost_reason', label: 'Cost' },
        { scoreField: 'documentation_score', reasonField: 'documentation_reason', label: 'Documentation' },
        { scoreField: 'overall_score', reasonField: 'overall_reason', label: 'Overall' }
    ];

    var errors = [];

    for (var i = 0; i < SCORE_REASON_PAIRS.length; i++) {
        var pair = SCORE_REASON_PAIRS[i];
        var scoreValue = current.getValue(pair.scoreField);
        if (scoreValue !== null && scoreValue !== '' && !current[pair.scoreField].nil()) {
            var reasonValue = current.getValue(pair.reasonField);
            if (reasonValue === null || reasonValue === '' || reasonValue.toString().trim() === '') {
                errors.push(pair.label + ' rating reason is required when a ' + pair.label.toLowerCase() + ' score is provided.');
            }
        }
    }

    if (errors.length > 0) {
        for (var j = 0; j < errors.length; j++) {
            gs.addErrorMessage(errors[j]);
        }
        current.setAbortAction(true);
    }
})(current, previous);
